        response = response + "Content-Length: 45\r\n";
        response = response + "\r\n";
        response = response + "<html><body>Hello from FreeLang HTTP!</body></html>";
        return response;
    }

    if (status == 404) {
        response = "HTTP/1.1 404 Not Found\r\n";
        response = response + "Content-Type: text/plain\r\n";
        response = response + "Content-Length: 9\r\n";
        response = response + "\r\n";
        response = response + "Not Found";
        return response;
    }

    return "HTTP/1.1 500 Internal Server Error\r\n\r\n";
}

// Main server function
fn main() -> i64 {
    var port: i64 = 8080;
    var max_connections: i64 = 100;
    var request_count: i64 = 0;

