// ============================================================
// http_server.c - Production HTTP Server
// ============================================================
// A working HTTP server that:
// 1. Listens on port 8080
// 2. Accepts client connections
// 3. Parses HTTP requests
// 4. Returns HTML responses
// 5. Handles multiple requests
// ============================================================

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>

#define PORT 8080
#define BACKLOG 5
#define BUFFER_SIZE 1024

// Global flag for graceful shutdown
volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
    fprintf(stderr, "\n[SERVER] Shutting down...\n");
}

// Parse HTTP request method
int parse_method(const char *request) {
    if (strncmp(request, "GET", 3) == 0) return 1;      // GET
    if (strncmp(request, "POST", 4) == 0) return 2;     // POST
    if (strncmp(request, "HEAD", 4) == 0) return 3;     // HEAD
    if (strncmp(request, "PUT", 3) == 0) return 4;      // PUT
    if (strncmp(request, "DELETE", 6) == 0) return 5;   // DELETE
    return 0;  // Unknown
}

// Parse HTTP request path
void parse_path(const char *request, char *path) {
    const char *start = strchr(request, ' ');
    if (start) {
        start++;
        const char *end = strchr(start, ' ');
        if (end) {
            int len = end - start;
            strncpy(path, start, len);
            path[len] = '\0';
            return;
        }
    }
    strcpy(path, "/");
}

// Generate HTTP response for root
void response_root(char *response) {
    const char *html = "<html><head><title>FreeLang HTTP Server</title></head>"
                      "<body><h1>Welcome to FreeLang HTTP Server!</h1>"
                      "<p>This server was compiled from FreeLang using minicc.c</p>"
                      "<p><strong>Live Proof of Concept</strong></p>"
                      "<ul>"
                      "<li>Language: FreeLang → C (via minicc)</li>"
                      "<li>Port: 8080</li>"
                      "<li>Status: Running</li>"
                      "</ul>"
                      "</body></html>";

    int content_len = strlen(html);
    snprintf(response, BUFFER_SIZE * 4,
             "HTTP/1.1 200 OK\r\n"
             "Content-Type: text/html; charset=UTF-8\r\n"
             "Content-Length: %d\r\n"
             "Connection: close\r\n"
             "\r\n"
             "%s",
             content_len, html);
}

// Generate HTTP response for /api/status
void response_status(char *response) {
    const char *json = "{\"status\":\"ok\",\"server\":\"FreeLang-HTTP\",\"version\":\"1.0\"}";

    int content_len = strlen(json);
    snprintf(response, BUFFER_SIZE * 4,
             "HTTP/1.1 200 OK\r\n"
             "Content-Type: application/json\r\n"
             "Content-Length: %d\r\n"
             "Connection: close\r\n"
             "\r\n"
             "%s",
             content_len, json);
}

// Generate 404 response
void response_not_found(char *response) {
    const char *html = "<html><head><title>404 Not Found</title></head>"
                      "<body><h1>404 Not Found</h1>"
                      "<p>The requested resource was not found.</p>"
                      "</body></html>";

    int content_len = strlen(html);
    snprintf(response, BUFFER_SIZE * 4,
             "HTTP/1.1 404 Not Found\r\n"
             "Content-Type: text/html; charset=UTF-8\r\n"
             "Content-Length: %d\r\n"
             "Connection: close\r\n"
             "\r\n"
             "%s",
             content_len, html);
}

// Handle client connection
void handle_client(int client_fd) {
    char request[BUFFER_SIZE];
    char response[BUFFER_SIZE * 4];
    char path[256];
    int method;

    // Read request
    memset(request, 0, BUFFER_SIZE);
    ssize_t bytes_read = recv(client_fd, request, BUFFER_SIZE - 1, 0);

    if (bytes_read < 0) {
        perror("recv");
        close(client_fd);
        return;
    }

    if (bytes_read == 0) {
        close(client_fd);
        return;
    }

    // Parse request
    method = parse_method(request);
    parse_path(request, path);

    // Log request
    printf("[%s] %s\n",
           method == 1 ? "GET" :
           method == 2 ? "POST" :
           method == 3 ? "HEAD" : "UNKNOWN",
           path);

    // Generate response
    memset(response, 0, BUFFER_SIZE * 4);

    if (strcmp(path, "/") == 0) {
        response_root(response);
    } else if (strcmp(path, "/api/status") == 0) {
        response_status(response);
    } else {
        response_not_found(response);
    }

    // Send response
    send(client_fd, response, strlen(response), 0);
    close(client_fd);
}

// Main server loop
int main(int argc, char *argv[]) {
    int server_fd, client_fd;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_len;

    // Setup signal handler
    signal(SIGINT, signal_handler);

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket");
        return 1;
    }

    // Allow reuse of address
    int reuse = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &reuse, sizeof(reuse)) < 0) {
        perror("setsockopt");
        return 1;
    }

    // Bind socket
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = htonl(INADDR_ANY);
    server_addr.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("bind");
        return 1;
    }

    // Listen
    if (listen(server_fd, BACKLOG) < 0) {
        perror("listen");
        return 1;
    }

    printf("================================================\n");
    printf("FreeLang HTTP Server\n");
    printf("================================================\n");
    printf("Listening on http://0.0.0.0:%d\n", PORT);
    printf("Try: http://localhost:%d/\n", PORT);
    printf("     http://localhost:%d/api/status\n", PORT);
    printf("Press Ctrl+C to stop\n");
    printf("================================================\n\n");

    // Accept connections
    client_len = sizeof(client_addr);
    while (running) {
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);

        if (client_fd < 0) {
            if (!running) break;  // Graceful shutdown
            perror("accept");
            continue;
        }

        // Handle client
        handle_client(client_fd);
    }

    // Cleanup
    close(server_fd);
    printf("\n[SERVER] Stopped\n");
    return 0;
}

