    }

    // Parse request
    method = parse_method(request);
    parse_path(request, path);

    // Log request
    printf("[%s] %s\n",
           method == 1 ? "GET" :
           method == 2 ? "POST" :
           method == 3 ? "HEAD" : "UNKNOWN",
           path);

    // Generate response
    memset(response, 0, BUFFER_SIZE * 4);

    if (strcmp(path, "/") == 0) {
        response_root(response);
    } else if (strcmp(path, "/api/status") == 0) {
        response_status(response);
    } else {
        response_not_found(response);
    }

    // Send response
    send(client_fd, response, strlen(response), 0);
    close(client_fd);
}

// Main server loop
int main(int argc, char *argv[]) {
    int server_fd, client_fd;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_len;

    // Setup signal handler
    signal(SIGINT, signal_handler);

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket");
        return 1;
    }

    // Allow reuse of address
    int reuse = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &reuse, sizeof(reuse)) < 0) {
        perror("setsockopt");
        return 1;
    }

    // Bind socket
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = htonl(INADDR_ANY);
    server_addr.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("bind");
        return 1;
    }

    // Listen
    if (listen(server_fd, BACKLOG) < 0) {
        perror("listen");
        return 1;
    }

    printf("================================================\n");
    printf("FreeLang HTTP Server\n");
    printf("================================================\n");
    printf("Listening on http://0.0.0.0:%d\n", PORT);
    printf("Try: http://localhost:%d/\n", PORT);
    printf("     http://localhost:%d/api/status\n", PORT);
    printf("Press Ctrl+C to stop\n");
    printf("================================================\n\n");

    // Accept connections
    client_len = sizeof(client_addr);
    while (running) {
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);

        if (client_fd < 0) {
            if (!running) break;  // Graceful shutdown
            perror("accept");
            continue;
        }

        // Handle client
        handle_client(client_fd);
    }

    // Cleanup
    close(server_fd);
    printf("\n[SERVER] Stopped\n");
    return 0;
}

